sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    //initialize Script Include
    var ghssHelper = new x_hsb11_mss_c_ghss.GHSS_Helper();
    current.state = 'processing_ghss';
    var sourceSystem = current.sn_task.trade_id.source_system.toString();
    var ghssSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGHSSWidgetTriggerSourceSystem');
    var gcsSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGCSWidgetTriggerSourceSystem');
    var trdOwningBusiness = current.sn_task.trade_id.owning_business.toString();

    try {
        // MSSCUSTODY- 4148,MSSCUSTODY-4721 - Added check for source system and owning business 
        if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1) && (trdOwningBusiness != 'GC HK')) {
            switch (current.request_type.toString()) {
                case 'confirm_ghss':
                    ghssHelper.confirm_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.sys_id); //function call for confirm ghss script include method.
                    break;
                case 'resume_ghss':
                    ghssHelper.resume_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.suspense_trade_status, current.remark, current.reason_code, current.sys_id); //function call for resume ghss script include method.
                    break;
                case 'hold_ghss':
                    ghssHelper.hold_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.suspense_trade_status, current.remark, current.reason_code, current.sys_id); //function call for hold ghss script include method.
                    break;
                case 'settle_ghss':
                    ghssHelper.settle_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.settle_indicator, current.auto_resume_indicator, current.remark, current.sys_id); //function call for settle ghss script include method.
                    break;
                case 'cancel_ghss':
                    ghssHelper.cancel_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.cancel_code, current.cancelled_by_indicator, current.collect_charge_indicator, current.cancel_reference, current.remark, current.sys_id); //function call for cancel ghss script include method.
                    break;

            }
        }
        // MSSCUSTODY-4148,MSSCUSTODY-4721 -  Added check for source system and owning business 
        else if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') > -1)) {
            switch (current.request_type.toString()) {
                case 'confirm_ghss':
                    ghssHelper.confirm_fun_gcs(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.value_date, current.sys_id); //function call for confirm ghss script include method. // MSSCUSTODY-4148 - Added value date in function call.
                    break;
                case 'resume_ghss':
                    ghssHelper.resume_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.suspense_trade_status, current.remark, current.reason_code, current.sys_id); //function call for resume ghss script include method.
                    break;
                case 'hold_ghss':
                    ghssHelper.hold_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.suspense_trade_status, current.remark, current.reason_code, current.sys_id); //function call for hold ghss script include method.
                    break;
                case 'settle_ghss':
                    ghssHelper.settle_fun_gcs(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.settle_indicator, current.auto_resume_indicator, current.remark, current.value_date, current.settlement_date, current.sys_id); //function call for settle ghss script include method. // MSSCUSTODY-4148 - Added Vaue date and settlement date in function call
                    break;
                case 'cancel_ghss':
                    if (current.fxr_td) {
                        ghssHelper.cancel_fun_gcs(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.cancel_code, current.cancelled_by_indicator, current.collect_charge_indicator, current.cancel_reference, current.remark, current.getValue('fxr_td').toString(), current.sys_id); //function call for cancel ghss script include method. // MSSCUSTODY- 4148 - Added FXRTD in function call.

                    } else {
                        ghssHelper.cancel_fun_gcs_nofxIndicator(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.cancel_code, current.cancelled_by_indicator, current.collect_charge_indicator, current.cancel_reference, current.remark, null, current.sys_id); //function call for cancel ghss script include method. // MSSCUSTODY- 4148 - Added FXRTD in function call.

                    }



                    break;

            }
        }

		//MSSCUDTODY-6087, 6089, 6090
		if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness == 'GC HK')) { 
            switch (current.request_type.toString()) {
                case 'cancel_ghss':
                    ghssHelper.cancel_fun_gc(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.cancel_code, current.cancel_reference, current.cancelled_by_indicator, current.fx_cx, current.collect_charge_indicator, current.gdi_indicator, current.remark, current.sys_id); //function call for cancel ghss script include method.
                    break;

				case 'confirm_ghss':
                    ghssHelper.confirm_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.sys_id);
					break;

				case 'settle_ghss':
                    ghssHelper.settle_fun_gc(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.settle_indicator, current.value_date, current.settlement_date, current.remark, current.sys_id);
					break;

				case 'hold_ghss':
                    ghssHelper.hold_fun(current.maker, current.checker, current.reference, current.last_update_date_time, current.generate_advice, current.suspense_trade_status, current.remark, current.reason_code, current.sys_id); //function call for hold ghss script include method.
                    break;
            }
        }


    } catch (err) {
        gs.info(err);
    } finally {
        current.update();
    }

})(current, previous);
